function nav(user){return `<nav><a class="brand" href="/" aria-label="Podplane home">${logo}<small class="stage-badge">Staging</small></a><div class="links"><a class="text-link hide-small" href="/catalog">Shared library</a>${user?`<a class="text-link" href="/app">My feeds</a><a class="text-link" href="/settings">Account</a><form method="post" action="/auth/logout"><button class="text-link" type="submit">Sign out</button></form>`:'<a class="btn small" href="/signin">Sign in ↗</a>'}</div></nav>`;}
const footer=`<footer class="wrap"><span>© 2026 Podplane</span><span>Your feed is private. Keep its link to yourself.</span><div class="footer-links"><a href="/privacy">Privacy</a><a href="/terms">Terms</a></div></footer>`;
function landing(user){const wave=Array.from({length:67},(_,i)=>`<i class="${i>=23&&i<=36?'ad':''}" style="--h:${18+(i*37+Math.floor(i/3)*13)%71}%"></i>`).join('');const clean=Array.from({length:52},(_,i)=>`<i style="--h:${22+(i*29+Math.floor(i/3)*17)%75}%"></i>`).join('');return `${head('Make room for the conversation')}<body>${nav(user)}<main><section class="wrap hero"><div><div class="eyebrow"><span class="dot"></span> Podcast listening, uninterrupted</div><h1 class="serif">Make room<br>for the<br><em>conversation.</em></h1><p>Add a podcast. Podplane cuts out detected ads and gives you a private RSS feed for your favorite player.</p><div class="actions"><a class="btn" href="${user?'/app':'/signin'}" target="_top">${user?'Open my library':'Create your feed'} ↗</a><a class="text-link" href="#how-it-works">See how it works ↓</a></div><div class="note">Free beta · Email or passkey login</div></div><div class="illustration" role="img" aria-label="Illustration of a podcast waveform with a sponsor segment removed"><div class="top"><span>How a cut works</span><span class="pill">Illustration</span></div><h2 class="serif">A little less interruption.</h2><p>The conversation continues.</p><div class="wave">${wave}<label>Sponsor segment</label></div><div class="wave-caption"><span>ORIGINAL AUDIO</span><span>↓</span></div><div class="down">⌄</div><div class="clean-wave">${clean}</div><div class="illustration-bottom"><span>YOUR PRIVATE FEED</span><strong>Detected ad removed ✓</strong></div><div class="sticker">Ready for your podcast app ↗</div></div></section><div class="wrap"><div class="compat"><span>Listen wherever RSS works</span><div class="players"><span>YouTube Music</span><span>Apple Podcasts</span><span>Pocket Casts</span><span>Overcast</span></div></div></div><section class="wrap section" id="how-it-works"><div class="section-title"><div><div class="eyebrow">A familiar way to listen</div><h2 class="serif">Listen in the player you already use.</h2></div><p>Keep the player you already use. We take care of the episodes before they reach your queue.</p></div><div class="steps"><article class="step"><div class="step-num"><span>01 / ADD</span><span>＋</span></div><h3>Find your podcast.</h3><p>Choose a show from the shared library or add a publisher’s RSS feed. Cached episodes are ready immediately.</p></article><article class="step"><div class="step-num"><span>02 / PROCESS</span><span>⌁</span></div><h3>Let the ad breaks go.</h3><p>We transcribe the audio, identify likely paid advertising, and cut those segments from the MP3.</p></article><article class="step"><div class="step-num"><span>03 / LISTEN</span><span>↗</span></div><h3>Subscribe once.</h3><p>Copy your private feed into your player. We check for new releases every 30 minutes and add completed episodes.</p></article></div></section><div class="wrap"><section class="explain"><div><div class="eyebrow">A careful edit</div><h2 class="serif">Product talk can be<br>part of the conversation.</h2><p>Podplane looks for paid sponsor reads and commercial breaks. When a segment is uncertain, we favor keeping the discussion. You can see every detected cut in your library.</p><p>Automatic editing can make mistakes, and some ads may remain. MP3 feeds are supported in this beta.</p></div><div class="faq"><details><summary>Can I use YouTube Music?</summary><p>Yes. Open Library → Podcasts → Add podcast → Add a podcast by RSS feed, then paste your Podplane feed. A publisher’s audio RSS feed is required; YouTube-only videos are unsupported.</p></details><details><summary>Do new episodes arrive automatically?</summary><p>Yes. We check your shows every 30 minutes. Each new episode appears after processing completes. Your first import starts with the latest episode, and completed audio is available for 30 days.</p></details><details><summary>Who can open my feed?</summary><p>Anyone with its private link can access the audio. Keep it to yourself. You can replace the link in your library, which disables the previous link immediately.</p></details><details><summary>What are the beta limits?</summary><p>Five podcasts per account, MP3 episodes up to three hours or 220 MB, and a shared processing allowance of 600 audio minutes per day. There is no charge from Podplane during the beta.</p></details></div></section></div></main>${footer}</body></html>`;}

const client=String.raw`
const $=s=>document.querySelector(s);let state=null;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clock=n=>{n=Math.round(n);return Math.floor(n/60)+':'+String(n%60).padStart(2,'0');};
const art=url=>'<div class="art">'+(url&&url.startsWith('https://')?'<img src="'+esc(url)+'" alt="" loading="lazy" referrerpolicy="no-referrer">':'⌁')+'</div>';
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
async function api(path,method='GET',body){const r=await fetch('/api/'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json();}catch{throw Error('The server could not complete this request.');}if(!r.ok)throw Error(d.error||'Please try again.');return d;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Feed link copied.');}catch{prompt('Copy this private feed link:',text);}}
const labels={queued:'Queued',processing:'Downloading',transcribing:'Transcribing',detecting:'Finding ads',editing:'Editing audio',ready:'Ready',failed:'Needs attention'};
function render(d){state=d;$('#feed-url').value=d.feed_url;$('#stat-shows').textContent=d.shows.length;const ready=d.episodes.filter(e=>e.status==='ready');$('#stat-episodes').textContent=ready.length;$('#stat-time').textContent=Math.round(ready.reduce((n,e)=>n+Math.max(0,e.duration-e.cleaned_duration),0)/60);$('#show-count').textContent=d.shows.length+' / '+(d.max_shows===null?'Unlimited':d.max_shows);$('#plan-limits').textContent=d.plan==='unlimited'?'Unlimited plan · Unlimited shows and processing minutes.':'Free beta · Episodes up to 3 hours or 220 MB.';$('#add-limit').textContent=d.plan==='unlimited'?'MP3 audio feeds · Unlimited shows':'MP3 audio feeds · Up to 5 shows';
$('#shows').innerHTML=d.shows.length?d.shows.map(s=>'<article class="show">'+art(s.artwork)+'<div class="show-info"><h3>'+esc(s.title)+'</h3><p>'+esc(s.author||'Podcast')+' · '+s.ready_count+' ready</p>'+(s.last_error?'<p class="error">'+esc(s.last_error)+'</p>':'')+'</div><div class="show-buttons"><button data-feed="'+esc(s.feed_url)+'" aria-label="Copy RSS feed for '+esc(s.title)+'">RSS ↗</button><button class="remove" data-remove="'+s.id+'" aria-label="Remove '+esc(s.title)+'">✕</button></div></article>').join(''):'<div class="empty"><div class="empty-symbol">⌁</div><strong>Your next listen starts here.</strong>Search for a show or paste its RSS feed.<br>We’ll start with the latest episode.</div>';
$('#episodes').innerHTML=d.episodes.length?d.episodes.map(e=>{const busy=!['ready','failed','expired'].includes(e.status);return '<article class="episode"><div class="episode-row"><div class="episode-copy"><span class="status '+(e.status==='failed'?'failed':busy?'busy':'')+'">'+(busy?'◌ ':e.status==='ready'?'✓ ':'')+esc(labels[e.status]||e.status)+'</span><h3>'+esc(e.title)+'</h3><div class="episode-meta"><span>'+esc(e.podcast_title)+'</span><span>'+new Date(e.published_at*1000).toLocaleDateString(undefined,{month:'short',day:'numeric'})+'</span>'+(e.status==='ready'?'<span>'+clock(e.cleaned_duration)+' audio</span><span style="color:#648247">'+clock(Math.max(0,e.duration-e.cleaned_duration))+' removed</span>':'')+'</div>'+(busy?'<div class="progress" role="progressbar" aria-label="Episode processing" aria-valuenow="'+e.progress+'" aria-valuemin="0" aria-valuemax="100"><i style="width:'+e.progress+'%"></i></div>':'')+(e.error?'<p class="'+(e.status==='ready'?'note':'error')+'">'+esc(e.error)+'</p>'+(e.status==='failed'?'<button class="btn small outline" data-retry="'+e.id+'">Retry episode ↻</button>':''):'')+'</div>'+(e.status==='ready'?'<button class="play" data-play="'+e.id+'" aria-label="Play '+esc(e.title)+'">▶</button>':'')+'</div>'+(e.status==='ready'?'<div id="player-'+e.id+'" hidden><audio controls preload="none" src="'+esc(e.audio_url)+'"></audio></div>':'')+(e.cuts.length?'<details class="cuts"><summary>'+e.cuts.length+' detected ad '+(e.cuts.length===1?'segment':'segments')+'</summary><ol>'+e.cuts.map(c=>'<li>'+clock(c.start)+'–'+clock(c.end)+' · '+esc(c.sponsor)+'<br>'+esc(c.reason)+'</li>').join('')+'</ol>Times refer to the original episode.</details>':'')+'</article>';}).join(''):'<p class="note" style="padding:20px 0">Completed episodes will appear here and in your private feed.</p>';
}
async function load(){try{render(await api('dashboard'));$('#load-error').hidden=true;}catch(e){$('#load-error').textContent=e.message;$('#load-error').hidden=false;}}
$('#copy-feed').onclick=()=>state&&copy(state.feed_url);$('#feed-url').onclick=e=>e.target.select();
$('#rotate').onclick=async e=>{if(!confirm('Replace all private feed links? Your podcast apps will need the new links.'))return;const b=e.target;b.disabled=true;try{render(await api('rotate','POST',{}));toast('Previous links disabled. Add the new link to your player.');}catch(e){toast(e.message);}finally{b.disabled=false;}};
$('#refresh').onclick=async e=>{const b=e.target;b.disabled=true;try{render(await api('refresh','POST',{}));toast('Checked your shows. Recently checked feeds refresh every 30 minutes.');}catch(e){toast(e.message);}finally{b.disabled=false;}};
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.feed)return copy(b.dataset.feed);if(b.dataset.play){const p=$('#player-'+b.dataset.play);p.hidden=!p.hidden;if(!p.hidden){p.querySelector('audio').play().catch(()=>{});b.textContent='⌄';}else{p.querySelector('audio').pause();b.textContent='▶';}}if(b.dataset.remove){if(!confirm('Remove this podcast from your feeds?'))return;b.disabled=true;try{render(await api('podcasts/'+b.dataset.remove,'DELETE'));toast('Podcast removed.');}catch(e){toast(e.message);b.disabled=false;}}if(b.dataset.retry){b.disabled=true;try{render(await api('episodes/'+b.dataset.retry+'/retry','POST',{}));toast('Episode queued for another attempt.');}catch(e){toast(e.message);b.disabled=false;}}if(b.dataset.add)await add(b.dataset.add,b);});
async function add(url,b){b.disabled=true;const text=b.textContent;b.textContent='Adding…';try{render(await api('podcasts','POST',{feed_url:url,directory_id:b.dataset.directory}));$('#results').innerHTML='';$('#search-input').value='';toast('Podcast added to your private feed.');}catch(e){toast(e.message);}finally{b.disabled=false;b.textContent=text;}}
$('#search-form').onsubmit=async e=>{e.preventDefault();const q=$('#search-input').value.trim();if(!q)return;const b=$('#search-button');b.disabled=true;$('#search-error').hidden=true;if(/^https:\/\//i.test(q)){await add(q,b);return;}$('#results').innerHTML='<p class="note pulse" style="margin-top:20px">Searching podcasts…</p>';try{const r=await api('search?q='+encodeURIComponent(q));$('#results').innerHTML=r.results.length?r.results.map(s=>'<div class="result">'+art(s.artwork)+'<div class="result-title">'+esc(s.title)+'<small>'+esc(s.author)+'</small></div><button data-add="'+esc(s.feed_url)+'" data-directory="'+esc(s.directory_id)+'" aria-label="Add '+esc(s.title)+'">Add ＋</button></div>').join(''):'<p class="note" style="margin-top:20px">No shows found. Try the publisher’s RSS feed URL.</p>';}catch(e){$('#results').innerHTML='';$('#search-error').hidden=false;$('#search-error').textContent=e.message;}finally{b.disabled=false;}};
load();setInterval(()=>{if(!document.hidden&&![...document.querySelectorAll('audio')].some(a=>!a.paused))load();},20000);
`;
function dashboard(user){return `${head('My podcasts')}<body>${nav(user)}<main class="wrap"><div class="page-head"><div><div class="eyebrow"><span class="dot"></span> Your listening room</div><h1 class="serif">My podcasts.</h1><p>A private feed, a shorter queue.</p></div><button class="btn small outline" id="refresh">Refresh shows ↻</button></div><section class="feed-box"><div><div class="eyebrow">One feed for your library</div><h2>Your next episode lands here.</h2><p>Add this private RSS link to your podcast app.</p><div class="feed-url"><input id="feed-url" aria-label="Your private RSS feed URL" value="Loading your private link…" readonly><button class="btn lime" id="copy-feed">Copy link ↗</button></div></div><div class="feed-side"><span class="pill"><span class="dot"></span> Auto-refresh · 30 min</span><button id="rotate">Replace private links</button></div></section><div id="load-error" class="error" role="alert" hidden></div><div class="stats"><div class="stat"><strong id="stat-shows">0</strong><span>podcasts in your library</span></div><div class="stat"><strong id="stat-episodes">0</strong><span>episodes ready to play</span></div><div class="stat"><strong id="stat-time">0</strong><span>ad minutes removed</span></div></div><div class="dashboard-grid"><div><div class="subhead"><h2>Your shows</h2><span id="show-count">${user.unlimited?'Unlimited':'0 / 5'}</span></div><div class="shows" id="shows"><div class="loading pulse">Opening your library…</div></div><section class="episodes"><div class="subhead"><h2>Latest episodes</h2><span>30-day archive</span></div><div id="episodes"></div></section></div><aside><div class="add-card"><div class="eyebrow">Find your next listen</div><h2>Add a podcast.</h2><p>Search for a show or paste a public RSS feed. We’ll process its latest episode first.</p><form id="search-form"><label for="search-input" class="note" style="display:block;margin-bottom:7px">Podcast name or RSS URL</label><div class="input-row"><input id="search-input" placeholder="e.g. All-In, Radiolab…" required maxlength="1000" autocomplete="off"><button id="search-button" type="submit" aria-label="Search or add podcast">↗</button></div></form><div class="search-help" id="add-limit">MP3 audio feeds · ${user.unlimited?'Unlimited shows':'Up to 5 shows'}</div><div id="search-error" class="error" role="alert" hidden></div><div id="results"></div></div><p class="notice">For YouTube Music: Library → Podcasts → Add podcast → Add by RSS feed. Paste your private link.</p><p class="notice">Ad detection can miss ads or make an incorrect cut. Review the detected segments below each episode. Your feed contains completed episodes only.</p><p class="notice" id="plan-limits">${user.unlimited?'Unlimited plan · Unlimited shows and processing minutes.':'Free beta · Episodes up to 3 hours or 220 MB.'}</p></aside></div></main>${footer}<div id="toast" class="toast" role="status" hidden></div><script>${client}</script></body></html>`;}
function legal(user,type){const privacy=type==='privacy';return `${head(privacy?'Privacy':'Terms')}<body>${nav(user)}<main class="wrap legal"><div class="eyebrow">Podplane beta</div><h1 class="serif">${privacy?'Your listening stays yours.':'A few listening notes.'}</h1>${privacy?`<p>Podplane stores your sign-in identifier, podcast subscriptions, and processing history to create your private feeds. Podplane verifies your email with a one-time code sent through Cloudflare Email Service. Codes expire after 10 minutes, allow five attempts, and can be used once. You can also enroll a passkey. Podplane stores passkey public keys and hashed session tokens; biometric data stays with your authenticator.</p><h2>Audio and processing</h2><p>Publisher audio is downloaded to Cloudflare and transcribed using Workers AI. A language model identifies likely paid advertisements. Edited audio is stored for 30 days. Successful jobs delete their source audio and working transcripts. Failed jobs may retain temporary files for retry; those files are deleted after seven days.</p><h2>Private links</h2><p>RSS and audio links contain a secret access token. Anyone with a link can access its feed and audio. You can replace your links from your library at any time. Removing a show removes access to it through your account’s feed.</p><h2>Service providers</h2><p>Cloudflare hosts the processing service, database, and audio. Cloudflare Email Service delivers sign-in codes; Podplane verifies them and manages your session. The staging website runs on Cloudflare Workers. Search uses Apple’s podcast directory. Cover art loads from publishers and fonts load from Google Fonts. Those services receive ordinary connection information when used.</p><h2>Account deletion</h2><p>Deleting your account removes your account record and subscriptions and disables your private links. Shared publisher audio can remain cached until its retention period ends. Public-directory shows can appear in the shared catalog. Pasted feeds are kept out of the catalog unless independently listed in the public directory.</p>${user?'<button id="delete-account" class="btn outline">Delete my account</button><p id="delete-result" role="status"></p><script>document.getElementById("delete-account").onclick=async function(){if(!confirm("Delete your account, subscriptions and private feed links?"))return;this.disabled=true;try{const r=await fetch("/api/account",{method:"DELETE"});if(!r.ok)throw Error("Could not delete your account. Please try again.");location.href="/";}catch(e){document.getElementById("delete-result").textContent=e.message;this.disabled=false;}};</script>':''}`:`<p>Podplane is an experimental service for private, personal podcast listening. Use it only for audio you are permitted to access and process. Respect publishers’ rights and applicable terms.</p><h2>Editing accuracy</h2><p>Automatic ad detection can leave an ad in place or remove part of a discussion. Processed audio is provided as-is. Publisher attribution is retained; Podplane does not claim ownership of podcasts.</p><h2>Private use</h2><p>Keep feed links private. Do not publish, sell, or redistribute edited podcast audio. The service supports public HTTPS RSS feeds with MP3 audio.</p><h2>Beta limits</h2><p>Five shows per account, beginning with each show’s latest episode. Edited audio is kept for 30 days. Episodes are limited to three hours and 220 MB. The shared daily processing allowance is 600 audio minutes. Limits and availability may change.</p>`}</main>${footer}</body></html>`;}

const catalogClient=String.raw`
const catalogRoot=document.querySelector('#catalog-grid');
const catalogEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function loadCatalog(){if(!catalogRoot)return;try{const query=document.querySelector('#catalog-search')?.value||'',ready=document.querySelector('#catalog-ready')?.checked?'1':'0';const r=await fetch('/api/catalog?q='+encodeURIComponent(query)+'&ready='+ready);if(!r.ok)throw Error('Could not open the shared library. Please try again.');const d=await r.json(),items=catalogRoot.dataset.compact?d.podcasts.slice(0,3):d.podcasts;catalogRoot.innerHTML=items.length?items.map(p=>'<article class="catalog-card">'+(p.chart_rank?'<span class="chart-rank">#'+p.chart_rank+' in the US</span>':'')+'<div class="catalog-top"><div class="art">'+(p.artwork?.startsWith('https://')?'<img src="'+catalogEsc(p.artwork)+'" alt="" loading="lazy" referrerpolicy="no-referrer">':'⌁')+'</div><div><h3>'+catalogEsc(p.title)+'</h3><span class="category">'+catalogEsc(p.category)+' · '+catalogEsc(p.author)+'</span></div></div><p>'+catalogEsc(p.description)+'</p><div class="cache-info '+(p.ready_count?'':'pending')+'"><span class="dot" style="background:'+(p.ready_count?'#78994d':'#b8aa85')+'"></span>'+(p.ready_count?p.ready_count+' cached '+(p.ready_count===1?'episode ready':'episodes ready'):p.processing_count?'Processing an episode':'Processes when you add it')+'</div><button class="btn '+(p.subscribed?'selected':'')+'" data-follow="'+p.id+'" '+(p.subscribed?'disabled':'')+'>'+(p.subscribed?'✓ In your feed':p.ready_count?'Add cached episodes ＋':'Add to my feed ＋')+'</button></article>').join(''):'<p class="note">No shows match this search. You can add another podcast from your library.</p>';const count=document.querySelector('#catalog-count');if(count)count.textContent=items.length+' '+(items.length===1?'show':'shows')+(query?' matching your search':' available')+(d.chart?.count?' · Apple Podcasts US top '+d.chart.count+(d.chart.updated_at?' · '+new Date(d.chart.updated_at*1000).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):''):'');const e=document.querySelector('#catalog-error');if(e)e.hidden=true;}catch(e){const error=document.querySelector('#catalog-error');if(error){error.hidden=false;error.textContent=e.message;}}}
let searchTimer;document.querySelector('#catalog-search')?.addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(loadCatalog,250);});document.querySelector('#catalog-ready')?.addEventListener('change',loadCatalog);
document.addEventListener('click',async e=>{const b=e.target.closest('[data-follow]');if(!b)return;if(document.body.dataset.signedIn!=='true'){location.href='/signin';return;}b.disabled=true;b.textContent='Adding…';try{const r=await fetch('/api/podcasts',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({podcast_id:b.dataset.follow})});const d=await r.json();if(!r.ok)throw Error(d.error);if(typeof render==='function')render(d);if(typeof toast==='function')toast('Podcast added to your private feed.');await loadCatalog();}catch(e){b.disabled=false;b.textContent='Try again';const error=document.querySelector('#catalog-error');if(error){error.hidden=false;error.textContent=e.message;}}});
loadCatalog();
`;
function catalogPage(user){return `${head('Shared podcast library')}<body data-signed-in="${!!user}">${nav(user)}<main class="wrap"><div class="catalog-intro"><div class="eyebrow"><span class="dot"></span> A shared listening library</div><h1 class="serif">Choose a podcast.</h1><p>Browse the US top 200 on Apple Podcasts, plus shows already in the library. We process a show after someone adds it. Cached episodes are ready immediately.</p><div class="catalog-controls"><input type="search" id="catalog-search" aria-label="Search the shared library" placeholder="Search shows, hosts or categories…"><label><input id="catalog-ready" type="checkbox"> Cached episodes ready</label></div></div><p id="catalog-count" class="note" role="status" aria-live="polite"></p><p id="catalog-error" class="error" role="alert" hidden></p><div class="catalog-grid" id="catalog-grid"><p class="loading pulse">Opening the shared library…</p></div><div class="catalog-bottom">Looking for another show? <a class="text-link" href="${user?'/app':'/signin'}">${user?'Add it to your library':'Sign in to add a podcast'} ↗</a><br>Rankings come from <a class="text-link" href="https://podcasts.apple.com/us/charts" target="_blank" rel="noopener noreferrer">Apple Podcasts US charts ↗</a>. Your private feed links and account details stay private.</div></main>${footer}<script>${catalogClient}</script></body></html>`;}
const passkeyLogin=String.raw`document.querySelector('#passkey-login').onclick=async function(){const b=this;b.disabled=true;const error=document.querySelector('#auth-error');error.hidden=true;try{if(!window.PublicKeyCredential)throw Error('Passkeys are unavailable in this browser. Use email to continue.');const {startAuthentication}=await import('/assets/passkeys.js');const r=await fetch('/api/auth/passkeys/login/options',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const options=await r.json();if(!r.ok)throw Error(options.error);const credential=await startAuthentication({optionsJSON:options});const verify=await fetch('/api/auth/passkeys/login/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({credential})});const result=await verify.json();if(!verify.ok)throw Error(result.error);location.href='/app';}catch(e){error.hidden=false;error.textContent=e.name==='NotAllowedError'?'Passkey sign-in was cancelled. You can try again or use email.':e.message;}finally{b.disabled=false;}};`;
const emailLogin=String.raw`
const emailForm=document.querySelector('#email-form'),codeForm=document.querySelector('#code-form'),emailInput=document.querySelector('#email-address'),codeInput=document.querySelector('#email-code'),authError=document.querySelector('#auth-error'),emailStatus=document.querySelector('#email-status'),resend=document.querySelector('#resend-code');let sentEmail='',resendAt=0;
async function emailCall(path,body){const r=await fetch('/api/auth/email/'+path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||'Sign-in could not be completed. Please try again.');return d;}
function showAuthError(e){authError.textContent=e.message;authError.hidden=false;}
async function sendCode(button){button.disabled=true;authError.hidden=true;try{const d=await emailCall('start',{email:emailInput.value});sentEmail=d.email;resendAt=Date.now()+60000;emailForm.hidden=true;codeForm.hidden=false;emailStatus.textContent='We sent a six-digit code to '+sentEmail+'. It expires in 10 minutes.';codeInput.value='';codeInput.focus();}catch(e){showAuthError(e);}finally{button.disabled=false;updateResend();}}
function updateResend(){const seconds=Math.max(0,Math.ceil((resendAt-Date.now())/1000));resend.disabled=seconds>0;resend.textContent=seconds?'Resend code in '+seconds+'s':'Send a new code';}
emailForm.onsubmit=async e=>{e.preventDefault();await sendCode(document.querySelector('#send-code'));};
codeForm.onsubmit=async e=>{e.preventDefault();const b=document.querySelector('#verify-code');b.disabled=true;authError.hidden=true;try{await emailCall('verify',{code:codeInput.value});location.href='/app';}catch(e){showAuthError(e);b.disabled=false;}};
resend.onclick=()=>sendCode(resend);document.querySelector('#change-email').onclick=()=>{codeForm.hidden=true;emailForm.hidden=false;emailStatus.textContent='';authError.hidden=true;emailInput.focus();};setInterval(updateResend,1000);
`;
function signIn(user,message){return `${head('Sign in')}<body>${nav(user)}<main class="wrap auth-shell"><div><div class="eyebrow"><span class="dot"></span> Your private podcast feed</div><h1 class="serif">Good listening<br>starts here.</h1><p>Sign in with an email code, or use a passkey you’ve already saved. Choose podcasts from the shared library and keep listening in your usual player.</p><a class="text-link" href="/catalog">Browse the shared library ↗</a></div><section class="auth-card"><h2>Welcome to Podplane.</h2><p>We’ll email you a sign-in code. You can add a passkey from your account after signing in.</p><form id="email-form"><label for="email-address">Email address</label><input id="email-address" name="email" type="email" autocomplete="email" placeholder="you@example.com" maxlength="254" required><button class="btn" id="send-code" type="submit">Send me a code ↗</button></form><p id="email-status" role="status" aria-live="polite"></p><form id="code-form" hidden><label for="email-code">Sign-in code</label><input id="email-code" name="code" type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" placeholder="000000" required><button class="btn" id="verify-code" type="submit">Sign in ↗</button><div class="email-actions"><button id="resend-code" class="text-link" type="button">Send a new code</button><button id="change-email" class="text-link" type="button">Change email</button></div></form><div class="divider">or</div><button class="btn outline" id="passkey-login">Sign in with a passkey</button><p id="auth-error" class="error" role="alert" ${message?'':'hidden'}>${esc(message||'')}</p><p class="note" style="margin-top:24px">Staging · No password required.</p></section></main>${footer}<script>${emailLogin}${passkeyLogin}</script></body></html>`;}
const settingsClient=String.raw`
const pkError=document.querySelector('#passkey-error');async function pkCall(path,method='GET',body){const r=await fetch('/api/auth/passkeys'+path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(d.error);return d;}
const pkEsc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function loadKeys(){try{const d=await pkCall('');document.querySelector('#passkey-list').innerHTML=d.passkeys.length?d.passkeys.map(k=>'<div class="passkey-row"><div>'+pkEsc(k.name)+'<small>Added '+new Date(k.created_at*1000).toLocaleDateString()+(k.last_used_at?' · Last used '+new Date(k.last_used_at*1000).toLocaleDateString():'')+'</small></div><button data-remove-key="'+pkEsc(k.id)+'">Remove</button></div>').join(''):'<p class="note">You haven’t saved a passkey yet.</p>';}catch(e){pkError.hidden=false;pkError.textContent=e.message;}}
document.querySelector('#add-passkey').onclick=async function(){this.disabled=true;pkError.hidden=true;try{if(!window.PublicKeyCredential)throw Error('Passkeys are unavailable in this browser.');const {startRegistration}=await import('/assets/passkeys.js');const options=await pkCall('/register/options','POST',{});const credential=await startRegistration({optionsJSON:options});await pkCall('/register/verify','POST',{credential,name:document.querySelector('#passkey-name').value||'My passkey'});await loadKeys();}catch(e){pkError.hidden=false;pkError.textContent=e.name==='NotAllowedError'?'Passkey creation was cancelled.':e.message;}finally{this.disabled=false;}};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-remove-key]');if(!b)return;if(!confirm('Remove this passkey? You can still sign in with email.'))return;b.disabled=true;try{await pkCall('/'+encodeURIComponent(b.dataset.removeKey),'DELETE');await loadKeys();}catch(e){pkError.hidden=false;pkError.textContent=e.message;b.disabled=false;}});loadKeys();
`;
function settingsPage(user){return `${head('Account')}<body>${nav(user)}<main class="wrap"><div class="page-head"><div><div class="eyebrow">Your account</div><h1 class="serif">A simpler sign-in.</h1><p>${esc(user.email)}</p></div></div><div class="settings-grid"><section class="settings-card"><h2>Passkeys</h2><p>Save a passkey to sign in with your device’s fingerprint, face recognition or screen lock. Your private key stays with your authenticator.</p><div id="passkey-list"><p class="note">Loading passkeys…</p></div><label class="note" for="passkey-name">Name this passkey</label><div class="settings-actions"><input id="passkey-name" maxlength="80" placeholder="e.g. My phone"><button id="add-passkey" class="btn">Add a passkey ＋</button></div><p id="passkey-error" class="error" role="alert" hidden></p><p class="note">If your session is more than 15 minutes old, <a class="text-link" href="/signin">sign in again</a> before adding or removing a passkey.</p></section><section class="settings-card"><h2>Account plan</h2><p>${user.unlimited?'Unlimited · No show or daily processing allowance limits. Longer episodes and larger audio files are enabled.':'Free beta · Five shows and the shared daily processing allowance.'}</p></section><section class="settings-card"><h2>Email access</h2><p>${esc(user.email)}<br>Your verified email can always be used to sign in with a one-time code.</p></section><a class="text-link" href="/privacy">Privacy and account deletion ↗</a></div></main>${footer}<script>${settingsClient}</script></body></html>`;}
function sharedDashboard(user){let page=dashboard(user);page=page.replace('<body>','<body data-signed-in="true">');page=page.replace('<div class="dashboard-grid">','<section class="shared-section"><div class="subhead"><h2>From the shared library</h2><a class="text-link" href="/catalog">Browse all shows ↗</a></div><p id="catalog-error" class="error" role="alert" hidden></p><div class="catalog-grid" data-compact="true" id="catalog-grid"><p class="note pulse">Opening the shared library…</p></div></section><div class="dashboard-grid">');return page.replace('</body>',`<script>${catalogClient}</script></body>`);}
export default {
  async fetch(request,env){
    const url=new URL(request.url),path=url.pathname;
    if(!env.PODPLANE_NATIVE_AUTH)return Response.redirect('https://podplane-staging.challoner.dev'+path+url.search,302);
    const user=env.PODPLANE_USER||null;
    const headers={'Content-Type':'text/html; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer','Permissions-Policy':'camera=(), microphone=(), geolocation=(), publickey-credentials-get=(self), publickey-credentials-create=(self)'};
    if(path==='/app'||path==='/settings'){if(!user)return Response.redirect(url.origin+'/signin',302);return new Response(path==='/app'?sharedDashboard(user):settingsPage(user),{headers});}
    if(path==='/signin')return new Response(signIn(user,url.searchParams.get('error')),{headers});
    if(path==='/catalog')return new Response(catalogPage(user),{headers});
    if(path==='/')return new Response(landing(user),{headers});
    if(path==='/privacy'||path==='/terms')return new Response(legal(user,path.slice(1)),{headers});
    if(path==='/robots.txt')return new Response('User-agent: *\nDisallow: /\n');
    return new Response('Not found',{status:404});
  }
};
